export function getSkillGapData(userSkills, targetNodeSkills) {
  const categories = {
    Technical: { user: 0, required: 0 },
    Leadership: { user: 0, required: 0 },
    Communication: { user: 0, required: 0 },
    'Domain Knowledge': { user: 0, required: 0 },
    Certifications: { user: 0, required: 0 },
  };

  categories.Technical.user = userSkills.filter(s => technicalSkills.includes(s)).length;
  categories.Technical.required = targetNodeSkills.filter(s => technicalSkills.includes(s)).length;
  categories.Leadership.user = userSkills.filter(s => leadershipSkills.includes(s)).length;
  categories.Leadership.required = targetNodeSkills.filter(s => leadershipSkills.includes(s)).length;
  categories.Communication.user = userSkills.filter(s => communicationSkills.includes(s)).length;
  categories.Communication.required = targetNodeSkills.filter(s => communicationSkills.includes(s)).length;
  categories['Domain Knowledge'].user = userSkills.filter(s => domainSkills.includes(s)).length;
  categories['Domain Knowledge'].required = targetNodeSkills.filter(s => domainSkills.includes(s)).length;
  categories.Certifications.user = userSkills.filter(s => certSkills.includes(s)).length;
  categories.Certifications.required = targetNodeSkills.filter(s => certSkills.includes(s)).length;

  const missingSkills = targetNodeSkills.filter(s => !userSkills.includes(s));

  return { categories, missingSkills };
}
